(function() {
window.mondrianStencilsInline = {};
window.mondrianStencilsInline['mondrianIcons.housing.xml'] = '';
window.mondrianStencilsInline['mondrianIcons.network.xml'] = '';
window.mondrianStencilsInline['mondrianBase.xml'] = '';
window.mondrianStencilsInline['mondrianIcons.security.xml'] = '';
window.mondrianStencilsInline['mondrianIcons.products.xml'] = '';
window.mondrianStencilsInline['mondrianIcons.operations.xml'] = '';
window.mondrianStencilsInline['mondrianIcons.generic.xml'] = '';
window.mondrianStencilsInline['mondrianIcons.user.xml'] = '';
window.mondrianStencilsInline['mondrianIcons.platform.xml'] = '';

var l = mxStencilRegistry.loadStencilSet;

  mxStencilRegistry.loadStencilSet = function (filename, post) {
    var key = filename.substring(filename.lastIndexOf('/') + 1);
    var t = window.mondrianStencilsInline[key];

    if (t != null) {
      var xml = pako.inflateRaw(
        Uint8Array.from(atob(t), c => c.charCodeAt(0)),
        { to: 'string' }
      );
      var xmlDoc = mxUtils.parseXml(xml);
      mxStencilRegistry.parseStencilSet(xmlDoc.documentElement, post);
    } else if (l != null) {
      return l.apply(this, arguments); // fallback
    }
  };
})();
